    m.cpsAt = cps;
    m.fac = inp.power > 0 ? inp.power / cps(m.S0) : 1;
    m.boss = D.boss.concat(inp.noFut ? [] : futBoss(D.boss, inp.trail || D.trail, m.startMs)); m.relD = m.boss.filter((r) => r[7]).map((r) => r[7]).sort((a, b) => a - b); m.qt = D.qt; m.skip = D.skip || 18; m._tot = new Map();
