      g += '<line x1="' + ax.toFixed(1) + '" y1="' + ay.toFixed(1) + '" x2="' + bx.toFixed(1) + '" y2="' + by.toFixed(1) + '" stroke="' + k.color + '" stroke-width="2.5" stroke-linecap="round"/>';
      g += '<text x="' + ((ax + bx) / 2).toFixed(1) + '" y="' + (((ay + by) / 2) - 7).toFixed(1) + '" text-anchor="middle" font-size="11.5" font-weight="700" fill="' + k.color + '" stroke="var(--card)" stroke-width="3" paint-order="stroke">' + k.text + '</text></g>';
