    const clamp = () => { const v = svgEl(); if (!v) return; const w = v.clientWidth, h = v.clientHeight; z.x = Math.min(0, Math.max(w - w * z.k, z.x)); z.y = Math.min(0, Math.max(h - h * z.k, z.y)); };
    document.addEventListener('wheel', (e) => { const v = svgEl(); if (!v || !v.contains(e.target)) return; e.preventDefault(); const r = v.parentElement.getBoundingClientRect(), o = v.getBoundingClientRect(); const bx = o.left - z.x, by = o.top - z.y, cx = e.clientX - bx, cy = e.clientY - by; const k2 = Math.max(1, Math.min(10, z.k * (e.deltaY < 0 ? 1.18 : 1 / 1.18))); z.x = cx - (cx - z.x) * (k2 / z.k); z.y = cy - (cy - z.y) * (k2 / z.k); z.k = k2; if (k2 === 1) { z.x = 0; z.y = 0; } clamp(); apply(); }, { passive: false });
