    Object.keys(byMode).forEach((md) => { byMode[md].sort((x, y) => x.stages - y.stages).forEach((b, i, a) => { prev[b.no] = i ? a[i - 1].stages : 0; }); });
    const up = all.filter((b) => b.day > 0).map((b) => Object.assign({}, b, { gain: Math.max(0, b.stages - prev[b.no]) })).sort((x, y) => x.day - y.day || x.no - y.no);
