    M = E.buildModel(st, D);
    TR = E.simulate(M, null, true);
    const t = TR;
    const first = t.first;
    const allOk = first.every((x) => x > 0);
    const daysAll = allOk ? Math.max(...first) : 0;
    // 구매 횟수
    const cnt = st.pk.map(() => 0);
    t.rows.forEach((r) => r.flags.forEach((f, j) => (cnt[j] += f)));
    TR.cnt = cnt;
    const bill = t.bill;

