    h += '<div class="kpi bill"><small>총 과금액</small><b>' + won(bill) + '</b><span>' + (allOk ? '월 환산 약 ' + won(bill / Math.max(1, daysAll) * 30) : '1500일까지 누적한 값') + '</span></div>';
    h += '</div>' + boostHtml(t) + '<div class="tscroll"><table class="tbl"><thead><tr><th class="l">남는 재화</th><th>도달 일수</th><th>도달 날짜</th></tr></thead><tbody>';
    RES.forEach((n, k) => {
      const cl = reachCls[k];
      h += '<tr><td class="l rleft"><i class="ri ri' + k + '" title="' + ['코어더스트', '배틀데이터', '크레딧'][k] + '"></i>' + (allOk ? (Math.max(0, t.rows[daysAll - 1].cum[k] - M.Need[k]) / M.Boxes[t.rows[daysAll - 1].L - 1][k]).toLocaleString('ko-KR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + 'h' : '-') + '</td><td class="' + cl + '"><b>' + (first[k] ? first[k] + '일' : '미도달') + '</b></td><td>' + (first[k] ? dstr(first[k], true) : '-') + '</td></tr>';
    });
