    { const l0 = $('#u-L0'), pw = $('#u-power'); if (l0) l0.placeholder = M.autoL ? String(M.avgL) : ''; if (pw) pw.placeholder = Math.round(M.cpsAt(M.S0)).toLocaleString('ko-KR'); }
