      const nb = te.encode(name), db = te.encode(files[name]), crc = crc32(db);
      const lh = Uint8Array.from([].concat(u32(0x04034b50), u16(20), u16(0x0800), u16(0), u16(0), u16(0x21), u32(crc), u32(db.length), u32(db.length), u16(nb.length), u16(0)));
