        for (const mk of [() => blob, async () => new Uint8Array(await blob.arrayBuffer()), async () => new File([blob], filename, { type: mime })]) {
          try { await dl.save({ filename, data: await mk(), mimeType: mime }); done = true; break; } catch (e) { lastErr = e; if (e && /cancel|declin|denied|reject/i.test((e.code || '') + ' ' + (e.message || ''))) break; }
        }
        msg.textContent = done ? '엑셀 파일을 저장했습니다.' : (lastErr && /cancel|declin|denied|reject/i.test((lastErr.code || '') + ' ' + (lastErr.message || '')) ? '저장을 취소했습니다.' : '엑셀 파일을 저장하지 못했습니다.');
