    const byNo = (v) => M.boss.find((r) => String(r[0]) === String(v));
    const c = byNo($('#fix-cl').value);
    if (!c) { msg.textContent = '클리어한 가장 어려운 보스를 선택해 주세요.'; return; }
    const scRaw = $('#fix-sc').value.trim(), pcRaw = $('#fix-pc').value.trim();
    let sc = 0, pcv = 0;
    if (scRaw !== '') {
      sc = Math.round(+scRaw);
      if (!isFinite(sc) || sc < 1 || sc > M.S0) { msg.textContent = '클리어 당시 싱크로는 1 ~ 현재 싱크로(' + M.S0 + ') 사이여야 합니다. 비워 두면 무시합니다.'; return; }
    }
    if (pcRaw !== '') {
      pcv = +pcRaw;
      if (!isFinite(pcv) || pcv <= 0) { msg.textContent = '클리어 당시 투력은 0보다 큰 숫자여야 합니다. 비워 두면 무시합니다.'; return; }
      const cur = st.power > 0 ? st.power : TR.p0;
      if (pcv > cur * (st.power > 0 ? 1.05 : 1.5)) { msg.textContent = '클리어 당시 투력(' + fmt(pcv) + ')이 현재 ' + (st.power > 0 ? '1군 전투력' : '예상 투력') + '(' + fmt(cur) + ')보다 지나치게 높습니다. 값을 확인해 주세요.'; return; }
    }
    let P = TR.p0, extra = '';
