  function jwDialog() {
    let dlg = $('#jw-dlg');
    if (!dlg) { dlg = document.createElement('div'); dlg.id = 'jw-dlg'; dlg.className = 'jwdlg'; dlg.setAttribute('role', 'dialog'); dlg.setAttribute('aria-modal', 'true'); dlg.setAttribute('aria-label', '날짜 추가'); document.body.appendChild(dlg); }
    dlg.innerHTML = '<div class="jwdlgb"><h3>날짜 추가</h3><label>스케줄 이름<input type="text" id="jw-dn" maxlength="20" placeholder="예: 생일, 픽업 니케 출시"></label><label>날짜<input type="date" id="jw-dd" value="' + jwYmd(jwMs(todayStr()) + 30 * JW_DAY) + '"></label><p class="note bad" id="jw-dm" hidden></p><div class="jwdlgf"><button type="button" class="ghost sm" id="jw-dc">취소</button><button type="button" class="primary sm" id="jw-dok">추가</button></div></div>';
    dlg.hidden = false; setTimeout(() => { const i = $('#jw-dn'); if (i) i.focus(); }, 30);
    const close = () => { dlg.hidden = true; };
    dlg.onclick = (e) => {
      if (e.target === dlg || e.target.closest('#jw-dc')) { close(); return; }
      if (e.target.closest('#jw-dok')) {
        const nm = $('#jw-dn').value.trim(), dt = $('#jw-dd').value, m = $('#jw-dm');
        if (!(jwMs(dt) >= jwMs(todayStr()))) { m.textContent = '오늘 이후 날짜를 골라 주세요.'; m.hidden = false; return; }
        const j = jwS(); j.custom.push({ name: nm || '내 일정', date: dt }); j.sel = 'c:' + (j.custom.length - 1); close(); jwChanged(false);
      }
    };
    dlg.onkeydown = (e) => { if (e.key === 'Escape') close(); if (e.key === 'Enter' && e.target.id !== 'jw-dc') { const b = $('#jw-dok'); if (b) b.click(); } };
  }
