  /* ---------- 모집 탭 ----------
     쥬얼 탭의 날짜별 예상 보유량을 그대로 가져와, 그날까지 모인 재화로 픽업 확률을 계산하고 실제로 빠르게 뽑아 본다. */
  const GC_RATE = { pick: { pu: 0.02, ssr: 0.04, sr: 0.43 }, norm: { pu: 0, ssr: 0.04, sr: 0.43 }, love: { pu: 0.01, ssr: 0.02, sr: 0.43 } };
  const GC_MOLD = { purple: ['보라몰드', 0.21, 0.79], corp: ['기업몰드', 0.5, 0.3], perf: ['퍼펙트몰드', 1, 0], goldm: ['황금몰드', 0.61, 0] }; // [이름, SSR, SR] (황금몰드 나머지 39%는 하이퀄리티 퍼펙트몰드)
  const GC_CEIL = 200; // 골마 200 = 픽업 1명 교환
  /* 픽업 배너 목록: 새 픽업이 나오면 여기에 추가 (bt = 종류 번호, null = 직접 설정) */
  const GC_BANNERS = [{ name: '홍련 : 신살', start: '2026-11-05', bt: 1 }, { name: '마리안 : 퀸', start: '2026-10-29', bt: 1 }, { name: '직접 설정', bt: null }];
  const GC_BT = [['통상 픽업', 0.02], ['필그림·오버스펙 픽업', 0.01], ['필그림·오버스펙 복각', 0.01], ['위시리스트', 0]]; // 픽업 확률 (SSR은 모두 4%)
  const isWish = () => gcS().bt === 3;
  const gcBan = () => GC_BANNERS[gcS().b] || GC_BANNERS[GC_BANNERS.length - 1];
  const puName = () => (isWish() ? gcS().wt || '' : gcBan().bt == null ? '픽업 니케' : gcBan().name);
  const puRate = () => (isWish() ? gcWishRate() : GC_BT[gcS().bt] ? GC_BT[gcS().bt][1] : 0.02);
  /* 주년 모집 혜택 이벤트(1% 픽업 배너만): [누적 뽑기, 보상, 수량] */
  const GC_EV = [[20, '중급키트', 10], [60, '중급키트', 10], [100, '특뽑', 10], [140, '중급키트', 10], [180, '특뽑', 10], [220, '상급키트', 10], [260, '특뽑', 10], [300, '상급키트', 10], [370, '특뽑', 10], [440, '특뽑', 10], [520, '특뽑', 15], [600, '특뽑', 15], [700, '특뽑', 20]];
  const evOn = () => (gcS().bt === 1 || gcS().bt === 2) && gcS().ev !== false;
