    const ser = [{ name: (isWish() ? '위시 니케 ' : '픽업 ') + need + '장 이상', color: 'var(--c1)', pts }];
    const qs = [0.5, 0.8, 0.95].map((q) => [gcPullsFor(q, need, gold0), q * 100]).filter((x) => x[0] != null && x[0] <= top);
    if (qs.length) ser.push({ name: '50·80·95%', color: '#4fd18b', pts: qs, dots: true, noline: true });
    const gm = []; if (!isWish()) for (let k = 1; k * GC_CEIL - gold0 <= top; k++) { const x = k * GC_CEIL - gold0; if (x > 0) gm.push(x); }
    gm.forEach((x, i) => ser.push({ name: '골마 교환', nolegend: i > 0, color: '#ffc531', pts: [[x, 0], [x, 100]], dash: true }));
