    const tip = (i) => { const pt = pts[i]; if (!pt) return ''; const n = pt[0], e = gcEx(n, gold0); return '<b>' + (isWish() ? '모집 ' : '특뽑 ') + fmt(n) + '회</b><br>' + (isWish() ? '위시 니케 ' : '픽업 ') + need + '장 이상 ' + gcPct(gcProb(n, need, gold0)) + (e ? '<br>골마 교환 ' + e + '회 포함' : '') + (n <= N ? '<br><span style="color:#4fd18b">보유 재화로 가능</span>' : '<br><span style="color:#ff5d6c">' + fmt(n - N) + '회 부족</span>'); };
