    SR: [[3.6, 11, 25], [5.9, 19.8, 40], [7.8, 28.7, 55], [11.3, 41.3, 75], [15, 55, 100], [2.2, 8, 20], [3.3, 12, 30], [4.9, 18, 45], [7.6, 28, 70], [12.5, 50, 100], [1.2, 5.4, 15], [2.2, 9.9, 27.5], [3.1, 14.4, 40], [4.7, 21.6, 60], [10, 45, 100]],
